<?php ?><!doctype html><html lang="uz"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lavash N1 • Admin Ultra</title><style>:root{--bg:#080d18;--panel:#10182b;--line:#23304d;--text:#f8fafc;--muted:#8ea0bd;--hot:#ff5b00;--hot2:#ffae52;--ok:#20c978;--bad:#ef4444}*{box-sizing:border-box}body{margin:0;font:15px Inter,system-ui;background:radial-gradient(circle at 10% 0%,#ff5b0018,transparent 26%),radial-gradient(circle at 100% 0%,#ffae5212,transparent 22%),var(--bg);color:var(--text)}button,input,select,textarea{font:inherit}.login{min-height:100vh;display:grid;place-items:center;padding:20px}.box{background:linear-gradient(180deg,#121d34,#0d1527);border:1px solid var(--line);border-radius:28px;padding:24px;box-shadow:0 30px 80px #0008}.login .box{width:min(440px,100%)}.brand{font-size:25px;font-weight:1000;display:flex;gap:10px;align-items:center}.logo{width:48px;height:48px;border-radius:15px;display:grid;place-items:center;background:linear-gradient(135deg,var(--hot),var(--hot2))}.f{margin:14px 0}.f label{display:block;font-size:12px;color:#b7c3d8;font-weight:850;margin-bottom:6px}.f input,.f select,.f textarea,.select{width:100%;background:#0a1221;color:var(--text);border:1px solid var(--line);padding:12px;border-radius:13px}.btn{border:0;border-radius:13px;padding:11px 14px;font-weight:900;cursor:pointer}.primary{background:linear-gradient(135deg,var(--hot),var(--hot2));color:white}.ghost{background:#17223a;color:#d7dfed;border:1px solid var(--line)}.danger{background:var(--bad);color:white}.app{display:grid;grid-template-columns:250px 1fr;min-height:100vh}.side{padding:18px;border-right:1px solid var(--line);background:#070b14ee;position:sticky;top:0;height:100vh}.nav{display:grid;gap:7px;margin-top:22px}.nav button{background:none;border:1px solid transparent;color:#9fb0ca;text-align:left;padding:12px;border-radius:12px;font-weight:850;cursor:pointer}.nav button.active,.nav button:hover{background:#14203a;border-color:var(--line);color:#fff}.sideFoot{position:absolute;left:18px;right:18px;bottom:18px}.main{padding:22px;min-width:0}.top{display:flex;justify-content:space-between;gap:15px;align-items:flex-start;margin-bottom:20px}.top h1{margin:0;font-size:30px}.muted{color:var(--muted)}.live{display:flex;gap:8px;align-items:center;color:#88f0ba;font-weight:900}.dot{width:8px;height:8px;border-radius:50%;background:var(--ok);box-shadow:0 0 0 5px #20c97818}.tabs section{display:none}.tabs section.active{display:block}.stats{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px}.metric{padding:16px;border-radius:18px;background:linear-gradient(180deg,#101b31,#0c1526);border:1px solid var(--line)}.metric small{color:var(--muted)}.metric b{display:block;font-size:25px;margin-top:7px}.grid2{display:grid;grid-template-columns:1.3fr .7fr;gap:14px;margin-top:14px}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px}.card{padding:16px;border:1px solid var(--line);background:#0f1729;border-radius:18px}.tableWrap{overflow:auto}.table{border-collapse:collapse;width:100%;min-width:1100px}.table th,.table td{padding:11px;border-bottom:1px solid #1d2942;text-align:left;vertical-align:top}.table th{font-size:11px;color:#91a1bc}.badge{display:inline-block;border-radius:999px;padding:5px 8px;font-size:11px;font-weight:900}.b1{background:#3b240b;color:#fdba74}.b2{background:#082b1b;color:#86efac}.b3{background:#09253b;color:#7dd3fc}.b4{background:#20293a;color:#d3d9e3}.map{width:250px;overflow:hidden;border:1px solid var(--line);border-radius:13px;margin-top:8px}.map iframe{display:block;width:100%;height:145px;border:0}.link{display:inline-block;margin-top:5px;color:#ffb46b;text-decoration:none;font-weight:850}.toast{position:fixed;right:18px;bottom:18px;background:#101827;border:1px solid var(--line);padding:12px 14px;border-radius:12px;display:none}.err{margin-top:10px;padding:10px;border-radius:12px;background:#3a1414;color:#fecaca;border:1px solid #5f1d1d}@media(max-width:1200px){.stats{grid-template-columns:repeat(3,1fr)}.grid2{grid-template-columns:1fr}.cards{grid-template-columns:1fr 1fr}}@media(max-width:800px){.app{grid-template-columns:1fr}.side{position:relative;height:auto}.sideFoot{position:static;margin-top:14px}.main{padding:13px}.stats{grid-template-columns:1fr 1fr}.cards{grid-template-columns:1fr}.top h1{font-size:23px}}@media(max-width:520px){.stats{grid-template-columns:1fr}.nav{grid-template-columns:1fr 1fr}}
</style></head><body><div id="root"></div><div id="toast" class="toast"></div><script>
const API='panel_api.php',KEY='lavash_admin_ultra_2026';const root=document.getElementById('root');const toastBox=document.getElementById('toast');let products=[],couriers=[];const esc=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));const money=x=>Number(x||0).toLocaleString('uz-UZ')+' so‘m';const toast=t=>{toastBox.textContent=t;toastBox.style.display='block';setTimeout(()=>toastBox.style.display='none',1800)};
async function api(a,o={}){let t=localStorage.getItem(KEY)||'';let u=API+'?action='+encodeURIComponent(a)+(t?'&token='+encodeURIComponent(t):'')+'&_='+Date.now();let r=await fetch(u,{cache:'no-store',...o});let tx=await r.text();let d;try{d=JSON.parse(tx)}catch{throw Error('Server JSON javob bermadi (HTTP '+r.status+')')}return d}
function login(){root.innerHTML='<div class="login"><div class="box"><div class="brand"><span class="logo">🌯</span><span>Lavash N1<br><small class="muted">Admin Ultra</small></span></div><p class="muted">Boshqaruv markaziga kirish</p><form id="lf"><div class="f"><label>Login</label><input name="username" value="Daler" required></div><div class="f"><label>Parol</label><input name="password" value="Lavash" type="password" required></div><button class="btn primary" style="width:100%">Kirish</button><div id="le"></div></form></div></div>';document.getElementById('lf').onsubmit=async e=>{e.preventDefault();try{let d=await api('admin_login',{method:'POST',body:new FormData(e.target)});if(!d.ok)throw Error(d.message);localStorage.setItem(KEY,d.token);start()}catch(x){document.getElementById('le').innerHTML='<div class="err">'+esc(x.message)+'</div>'}}}
function ui(){root.innerHTML='<div class="app"><aside class="side"><div class="brand"><span class="logo">🌯</span><span>Lavash N1<br><small class="muted">Admin Ultra</small></span></div><div class="nav"><button class="active" data-id="dash">📊 Dashboard</button><button data-id="orders">📦 Buyurtmalar</button><button data-id="products">🌯 Mahsulotlar</button><button data-id="couriers">🛵 Kuryerlar</button><button data-id="customers">👥 Mijozlar</button><button data-id="history">🧾 Buyurtma tarixi</button><button data-id="settings">⚙️ Sozlamalar</button></div><div class="sideFoot"><button class="btn ghost" style="width:100%" onclick="localStorage.removeItem(KEY);location.reload()">Chiqish</button></div></aside><main class="main"><div class="top"><div><h1 id="ttl">Dashboard</h1><div class="muted">Jonli boshqaruv • 06:00–00:00 ish kuni</div></div><div class="live"><span class="dot"></span>SERVER ONLINE</div></div><div class="tabs"><section id="dash" class="active"><div class="stats" id="stat"></div><div class="grid2"><div class="box"><div style="display:flex;justify-content:space-between;align-items:center"><h2>🔥 Yangi buyurtmalar</h2><button class="btn ghost" onclick="ordersLoad()">↻</button></div><div id="new"></div></div><div class="box"><h2>🕘 Ish kuni</h2><div id="cycle" class="muted"></div><hr style="border-color:#23304d"><div id="health" class="muted"></div></div></div></section><section id="orders"><div class="box"><div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px"><select id="filter" class="select" onchange="ordersLoad()"><option value="">Barcha status</option><option value="new">Yangi</option><option value="confirmed">Tasdiqlangan</option><option value="preparing">Tayyorlanmoqda</option><option value="delivering">Yetkazilmoqda</option><option value="completed">Yakunlangan</option><option value="cancelled">Bekor</option></select><button class="btn ghost" onclick="ordersLoad()">↻ Yangilash</button></div><div id="ordersTable" class="tableWrap"></div></div></section><section id="products"><div class="box"><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn primary" onclick="addProduct()">＋ Mahsulot</button><input id="search" placeholder="Qidirish…" oninput="productsRender()" style="flex:1;min-width:180px" class="select"></div><div id="productsGrid" class="cards" style="margin-top:13px"></div></div></section><section id="couriers"><div class="box"><button class="btn primary" onclick="addCourier()">＋ Kuryer</button><div id="courierGrid" class="cards" style="margin-top:13px"></div></div></section><section id="customers"><div class="box"><h2>Mijozlar</h2><div id="customerGrid" class="cards"></div></div></section><section id="history"><div class="box"><div style="display:flex;justify-content:space-between;align-items:center"><h2>To‘liq buyurtma tarixi</h2><button class="btn ghost" onclick="historyLoad()">↻</button></div><div id="historyTable" class="tableWrap"></div></div></section><section id="settings"><div class="box"><h2>Do‘kon sozlamalari</h2><form id="settingsForm"><div class="grid2"><div><div class="f"><label>Do‘kon nomi</label><input name="store_name"></div><div class="f"><label>Telefon</label><input name="phone"></div><div class="f"><label>Manzil</label><input name="address"></div></div><div><div class="f"><label>Dastavka</label><input name="delivery_note"></div><div class="f"><label>Dastavka narxi</label><input name="delivery_fee" type="number"></div><div class="f"><label>Aksiya sarlavhasi</label><input name="promo_title"></div><div class="f"><label>Aksiya matni</label><textarea name="promo_text"></textarea></div></div></div><button class="btn primary">Saqlash</button></form></div></section></div></main></div>';document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav button').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.tabs section').forEach(s=>s.classList.toggle('active',s.id===b.dataset.id));document.getElementById('ttl').textContent=b.textContent.replace(/^\S+\s/,'')});document.getElementById('settingsForm').onsubmit=settingsSave}
async function start(){try{let m=await api('admin_me');if(!m.ok){login();return}ui();await Promise.all([summary(),ordersLoad(),productsLoad(),couriersLoad(),customersLoad(),settingsLoad()]);setInterval(summary,10000);setInterval(ordersLoad,10000)}catch(e){root.innerHTML='<div class="login"><div class="box"><h2>Server xatosi</h2><div class="err">'+esc(e.message)+'</div><button class="btn primary" style="width:100%;margin-top:12px" onclick="location.reload()">Qayta urinish</button></div></div>'}}
function badge(s){let c=s==='new'?'b1':s==='delivering'?'b3':s==='completed'||s==='cancelled'?'b4':'b2';return '<span class="badge '+c+'">'+esc(s)+'</span>'}
function map(x){let a=Number(x.lat),b=Number(x.lng);if(!Number.isFinite(a)||!Number.isFinite(b))return '<span class="muted">Lokatsiya yo‘q</span>';let q=encodeURIComponent(a+','+b);return '<div class="map"><iframe loading="lazy" src="https://maps.google.com/maps?q='+q+'&z=16&output=embed"></iframe></div><a class="link" target="_blank" rel="noopener" href="https://www.google.com/maps/dir/?api=1&destination='+q+'">🧭 Yo‘lni ochish</a>'}
async function summary(){let d=await api('summary');if(!d.ok)return;let x=d.data;document.getElementById('stat').innerHTML='<div class="metric"><small>Bugungi buyurtma</small><b>'+x.orders+'</b></div><div class="metric"><small>Bugungi savdo</small><b>'+money(x.sales)+'</b></div><div class="metric"><small>Yakunlangan</small><b>'+money(x.completed_sales)+'</b></div><div class="metric"><small>Yangi</small><b>'+x.new_count+'</b></div><div class="metric"><small>Yetkazilmoqda</small><b>'+x.delivering_count+'</b></div><div class="metric"><small>Online kuryer</small><b>'+x.online_couriers+'</b></div>';document.getElementById('cycle').textContent=new Date(x.business_start).toLocaleString('uz-UZ')+' → '+new Date(x.business_end).toLocaleString('uz-UZ');document.getElementById('health').textContent='Jami tarixdagi buyurtma: '+x.history_total}
let ord=[];async function ordersLoad(){let f=document.getElementById('filter')?.value||'';let d=await api('orders'+(f?'&status='+encodeURIComponent(f):''));if(!d.ok)return;ord=d.data||[];let c=await api('couriers');couriers=c.ok?c.data||[]:[];document.getElementById('ordersTable').innerHTML='<table class="table"><thead><tr><th>#</th><th>Mijoz</th><th>Manzil</th><th>Summa</th><th>Kuryer</th><th>Status</th></tr></thead><tbody>'+ord.map(x=>'<tr><td>#'+x.id+'<br><small class="muted">'+new Date(x.created_at).toLocaleString('uz-UZ')+'</small></td><td><b>'+esc(x.customer_name)+'</b><br>'+esc(x.phone)+'<br>'+((x.payment_method||'cash')==='card'?'💳 Karta':'💵 Naqd')+'<br>'+esc(x.note||'')+'</td><td>'+esc(x.address||'')+map(x)+'</td><td><b>'+money(x.amount)+'</b></td><td><select class="select" onchange="assign('+x.id+',this.value)"><option value="">Biriktirilmagan</option>'+couriers.map(k=>'<option value="'+k.id+'" '+(Number(k.id)===Number(x.courier_id)?'selected':'')+'>'+esc(k.name)+' • '+(k.online?'online':'offline')+'</option>').join('')+'</select></td><td><select class="select" onchange="statusChange('+x.id+',this.value)">'+['new','confirmed','preparing','delivering','completed','cancelled'].map(s=>'<option '+(s===x.status?'selected':'')+'>'+s+'</option>').join('')+'</select><br>'+badge(x.status)+'</td></tr>').join('')+'</tbody></table>';document.getElementById('new').innerHTML=ord.filter(x=>x.status==='new').slice(0,7).map(x=>'<div class="card" style="margin:9px 0"><b>#'+x.id+' • '+esc(x.customer_name)+'</b><br>'+money(x.amount)+'<br>'+esc(x.address||'')+'<br>'+map(x)+'<button class="btn primary" style="margin-top:8px" onclick="statusChange('+x.id+',\'confirmed\')">Tasdiqlash</button></div>').join('')||'<span class="muted">Yangi buyurtma yo‘q.</span>'}
async function statusChange(id,s){let f=new FormData();f.append('id',id);f.append('status',s);let d=await api('status',{method:'POST',body:f});toast(d.ok?'Status saqlandi':'Xato');ordersLoad();summary()}
async function assign(id,cid){if(!cid)return;let f=new FormData();f.append('order_id',id);f.append('courier_id',cid);let d=await api('assign',{method:'POST',body:f});toast(d.ok?'Kuryerga yuborildi':'Xato');ordersLoad()}
async function productsLoad(){let d=await api('products');if(d.ok){products=d.data||[];productsRender()}}
function productsRender(){let q=(document.getElementById('search')?.value||'').toLowerCase();let r=products.filter(p=>(p.p_title||'').toLowerCase().includes(q));document.getElementById('productsGrid').innerHTML=r.map(p=>'<div class="card"><h3 style="margin-top:0">🌯 '+esc(p.p_title)+'</h3><div class="muted">'+esc(p.p_desc||'')+'</div><h3>'+money(p.p_prize)+'</h3><button class="btn ghost" onclick="editProduct('+p.id+')">Tahrirlash</button> <button class="btn danger" onclick="delProduct('+p.id+')">O‘chirish</button></div>').join('')||'<div class="muted">Mahsulot topilmadi.</div>'}
async function addProduct(){let n=prompt('Mahsulot nomi');if(!n)return;let p=prompt('Narxi');if(p===null)return;let f=new FormData();[['id',0],['p_title',n],['p_subtitle',''],['p_desc',''],['p_prize',p],['cat_id','cat-20001'],['scat_id','scat-30001'],['p_image','dish-1.png'],['status','show']].forEach(([k,v])=>f.append(k,v));let d=await api('product_save',{method:'POST',body:f});toast(d.ok?'Mahsulot qo‘shildi':d.message||'Xato');productsLoad()}
async function editProduct(id){let p=products.find(x=>Number(x.id)===Number(id));if(!p)return;let n=prompt('Nomi',p.p_title),pr=prompt('Narxi',p.p_prize);if(n===null||pr===null)return;let f=new FormData();[['id',id],['p_title',n],['p_subtitle',p.p_subtitle||''],['p_desc',p.p_desc||''],['p_prize',pr],['cat_id',p.cat_id],['scat_id',p.scat_id],['p_image',p.p_image||'dish-1.png'],['status',p.status||'show']].forEach(([k,v])=>f.append(k,v));let d=await api('product_save',{method:'POST',body:f});toast(d.ok?'Saqlandi':'Xato');productsLoad()}
async function delProduct(id){if(!confirm('O‘chirilsinmi?'))return;let f=new FormData();f.append('id',id);let d=await api('product_delete',{method:'POST',body:f});toast(d.ok?'O‘chirildi':'Xato');productsLoad()}
async function couriersLoad(){let d=await api('couriers');if(!d.ok)return;couriers=d.data||[];document.getElementById('courierGrid').innerHTML=couriers.map(k=>'<div class="card"><h3>🛵 '+esc(k.name)+'</h3><div>'+esc(k.phone)+'</div><p><span class="badge '+(k.online?'b2':'b4')+'">'+(k.online?'ONLINE':'OFFLINE')+'</span></p><button class="btn ghost" onclick="editCourier('+k.id+')">Tahrirlash</button> <button class="btn danger" onclick="delCourier('+k.id+')">O‘chirish</button></div>').join('')||'<div class="muted">Kuryer yo‘q.</div>'}
async function addCourier(){let n=prompt('Ism');if(!n)return;let p=prompt('Telefon');if(!p)return;let pin=prompt('Parol');if(pin===null)return;let f=new FormData();[['id',0],['name',n],['phone',p],['pin',pin]].forEach(([k,v])=>f.append(k,v));let d=await api('courier_save',{method:'POST',body:f});toast(d.ok?'Kuryer qo‘shildi':'Xato');couriersLoad()}
async function editCourier(id){let k=couriers.find(x=>Number(x.id)===Number(id));if(!k)return;let n=prompt('Ism',k.name),p=prompt('Telefon',k.phone);if(n===null||p===null)return;let pin=prompt('Yangi parol (bo‘sh bo‘lsa o‘zgarmaydi)','');let f=new FormData();[['id',id],['name',n],['phone',p],['pin',pin]].forEach(([a,b])=>f.append(a,b));let d=await api('courier_save',{method:'POST',body:f});toast(d.ok?'Saqlandi':'Xato');couriersLoad()}
async function delCourier(id){if(!confirm('Kuryer o‘chirilsinmi?'))return;let f=new FormData();f.append('id',id);let d=await api('courier_delete',{method:'POST',body:f});toast(d.ok?'O‘chirildi':'Xato');couriersLoad()}
async function customersLoad(){let d=await api('customers');if(!d.ok)return;document.getElementById('customerGrid').innerHTML=(d.data||[]).map(x=>'<div class="card"><h3>👤 '+esc(x.name)+'</h3><div>📞 '+esc(x.phone)+'</div><div>✉️ '+esc(x.email||'')+'</div><div>📦 '+x.orders+' buyurtma</div><div>💰 '+money(x.spent)+'</div></div>').join('')||'<div class="muted">Mijoz yo‘q.</div>'}
async function historyLoad(){let d=await api('history');if(!d.ok)return;document.getElementById('historyTable').innerHTML='<table class="table"><thead><tr><th>#</th><th>Mijoz</th><th>Summa</th><th>Status</th><th>Kuryer</th><th>Sana</th></tr></thead><tbody>'+(d.data||[]).map(x=>'<tr><td>#'+x.id+'</td><td>'+esc(x.customer_name)+'<br>'+esc(x.phone)+'</td><td>'+money(x.amount)+'</td><td>'+badge(x.status)+'</td><td>'+esc(x.courier_name||'Biriktirilmagan')+'</td><td>'+new Date(x.created_at).toLocaleString('uz-UZ')+'</td></tr>').join('')+'</tbody></table>'}
async function settingsLoad(){let d=await api('settings');if(!d.ok)return;let f=document.getElementById('settingsForm');Object.keys(d.data).forEach(k=>{if(f.elements[k])f.elements[k].value=d.data[k]})}
async function settingsSave(e){e.preventDefault();let d=await api('settings',{method:'POST',body:new FormData(e.target)});toast(d.ok?'Sozlandi':'Xato')}
start();</script></body></html>
